WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS is_new_session FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT island_id, device_code, COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END) AS dv_04_count, MAX(is_new_session) FILTER (WHERE device_code = 'DV-02') AS dv_02_max_is_new_session, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, AVG(temp_c) FILTER (WHERE device_code = 'DV-03') AS dv_03_avg_temp_c, SUM(CASE WHEN device_code = 'DV-03' THEN pressure ELSE 0 END) AS dv_03_pressure FROM sessions_device_readings GROUP BY island_id, device_code ORDER BY dv_04_count NULLS LAST
